/*
 * Comparator: merge data/prices/<provider>/<service>.json with data/structure.js
 * and regenerate data/pricebook.js (GENERATED FILE — do not hand-edit).
 *
 * Run: node tools/build-pricebook.js
 * Idempotent. Numbers only come from price files; layout only from structure.js.
 */
'use strict';
const fs = require('fs'), path = require('path'), vm = require('vm');
const root = path.join(__dirname, '..');

const sandbox = { window: {} };
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(path.join(root, 'data/structure.js'), 'utf8'), sandbox);
const structure = sandbox.window.CA_STRUCTURE;

// load price files: prices[provider][service] = { tierLabel -> rowLabel -> price }
const pricesDir = path.join(root, 'data/prices');
const prices = {};
const sources = {};
for (const prov of fs.readdirSync(pricesDir)) {
  const pDir = path.join(pricesDir, prov);
  if (!fs.statSync(pDir).isDirectory()) continue;
  prices[prov] = {}; sources[prov] = {};
  for (const f of fs.readdirSync(pDir)) {
    if (!f.endsWith('.json')) continue;
    const data = JSON.parse(fs.readFileSync(path.join(pDir, f), 'utf8'));
    const svc = data.service;
    prices[prov][svc] = {};
    sources[prov][svc] = data.sources || [];
    for (const sku of data.skus) {
      const t = (prices[prov][svc][sku.tier] = prices[prov][svc][sku.tier] || {});
      t[sku.label] = sku.price;
    }
  }
}

const providers = Object.keys(prices);
const services = structure.services.map(svc => ({
  id: svc.id,
  tiers: svc.tiers.map(tier => ({
    label: tier.label,
    sub: tier.sub,
    products: tier.products,
    rows: tier.rows.map(row => {
      const p = {};
      let computed = null;
      const vals = providers.map(pv => {
        const v = prices[pv] && prices[pv][svc.id] && prices[pv][svc.id][tier.label]
          ? prices[pv][svc.id][tier.label][row.label] : null;
        p[pv] = v == null ? null : v;
        return v;
      });
      const [a, b] = vals;
      if (a != null && b != null) computed = Math.round((a - b) / b * 100);
      return { label: row.label, prices: p, delta: computed != null ? computed : row.delta };
    })
  }))
}));

const out = `/*
 * GENERATED by tools/build-pricebook.js — do not hand-edit.
 * Numbers: data/prices/<provider>/<service>.json · Layout: data/structure.js
 * Generated: ${new Date().toISOString().slice(0, 10)}
 */
var CA_DATA = window.CA_DATA = window.CA_DATA || {};
CA_DATA.providers = {
  tencent: { name: 'Tencent Cloud', short: 'Tencent' },
  aws: { name: 'AWS', short: 'AWS' },
  azure: { name: 'Microsoft Azure', short: 'Azure', pending: true },
  gcp: { name: 'Google Cloud', short: 'GCP', pending: true },
  alibaba: { name: 'Alibaba Cloud', short: 'Alibaba', pending: true }
};
CA_DATA.pricebooks = ${JSON.stringify([{
  id: structure.book, region: 'Frankfurt',
  regionDetail: { tencent: 'regionId 17', aws: 'eu-central-1' },
  currency: 'USD', unit: 'per month', retrieved: '2 Oct 2026',
  services
}], null, 2)};
`;
fs.writeFileSync(path.join(root, 'data/pricebook.js'), out);

let rows = 0, missing = 0;
services.forEach(s => s.tiers.forEach(t => t.rows.forEach(r => {
  rows++;
  if (r.prices.tencent == null || r.prices.aws == null) missing++;
})));
console.log('pricebook.js regenerated:', services.length, 'services,', rows, 'rows,', missing, 'with a missing side');
